def create_ticket(title, description='', priority=1, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0328000" if __import__("os").path.isdir("./environment_mix/0328000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    try:
        state = _load("state.json")
        if not isinstance(state, dict):
            state = {}
    except Exception as e:
        return _err("NOT_FOUND", "Datastore unavailable.", detail=str(e))

    # Ensure state shape
    if "ticket_queue" not in state or not isinstance(state.get("ticket_queue"), list):
        state["ticket_queue"] = []
    if "ticket_counter" not in state or not isinstance(state.get("ticket_counter"), int):
        state["ticket_counter"] = 1

    # Auth (ambient session)
    cur = state.get("current_user")
    if not isinstance(cur, str) or cur.strip() == "":
        return _err("UNAUTHORIZED", "User not authenticated. Please log in to create a ticket.")

    allowed_users = {"alice", "bob", "carol", "dave", "eve", "frank"}
    if cur not in allowed_users:
        return _err("UNAUTHORIZED", "Authenticated session is not permitted to access the ticketing service.")

    # Validate inputs
    if not isinstance(title, str):
        return _err("VALIDATION_ERROR", "title must be a string.")
    if title.strip() == "":
        return _err("VALIDATION_ERROR", "title is required and must not be empty.")
    if description is None:
        description = ""
    if not isinstance(description, str):
        return _err("VALIDATION_ERROR", "description must be a string.")
    if not isinstance(priority, int):
        return _err("VALIDATION_ERROR", "priority must be an integer.")
    if priority < 1 or priority > 5:
        return _err("VALIDATION_ERROR", "Invalid priority. Priority must be between 1 and 5.")

    # Generate id (ensure monotonic and unique)
    existing_ids = [t.get("id") for t in state["ticket_queue"] if isinstance(t, dict)]
    max_existing = 0
    for i in existing_ids:
        if isinstance(i, int) and i > max_existing:
            max_existing = i
    next_id = state["ticket_counter"]
    if not isinstance(next_id, int) or next_id <= max_existing:
        next_id = max_existing + 1

    ticket = {
        "id": next_id,
        "title": title,
        "description": description,
        "status": "Open",
        "priority": priority,
        "created_by": cur,
        "resolution": ""
    }

    state["ticket_queue"].append(ticket)
    state["ticket_counter"] = next_id + 1

    # Record service dynamics in-state (no separate audit collection in schema)
    state["random_seed"] = int(state.get("random_seed", 0) or 0) + 1

    try:
        _save("state.json", state)
    except Exception as e:
        return _err("CONFLICT", "Failed to persist ticket.", detail=str(e))

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {"ticket": ticket, "meta": {"latency_ms": latency_ms}}

def edit_ticket(ticket_id, updates, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0328000" if __import__("os").path.isdir("./environment_mix/0328000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()
    try:
        state = _load("state.json")
        if not isinstance(state, dict):
            state = {}
    except Exception as e:
        return _err("NOT_FOUND", "Datastore unavailable.", detail=str(e))

    if "ticket_queue" not in state or not isinstance(state.get("ticket_queue"), list):
        state["ticket_queue"] = []

    # Auth (ambient session)
    cur = state.get("current_user")
    if not isinstance(cur, str) or cur.strip() == "":
        return _err("UNAUTHORIZED", "User not authenticated. Please log in to edit tickets.")

    allowed_users = {"alice", "bob", "carol", "dave", "eve", "frank"}
    if cur not in allowed_users:
        return _err("UNAUTHORIZED", "Authenticated session is not permitted to access the ticketing service.")

    # Validate inputs
    if not isinstance(ticket_id, int):
        return _err("VALIDATION_ERROR", "ticket_id must be an integer.")
    if not isinstance(updates, dict) or len(updates) == 0:
        return _err("VALIDATION_ERROR", "updates must be a non-empty dictionary.")

    allowed_fields = {"title", "description", "status", "priority", "resolution"}
    unknown = [k for k in updates.keys() if k not in allowed_fields]
    if unknown:
        return _err("VALIDATION_ERROR", "updates contains unsupported fields.", unsupported_fields=unknown)

    # Find ticket
    idx = None
    for i, t in enumerate(state["ticket_queue"]):
        if isinstance(t, dict) and t.get("id") == ticket_id:
            idx = i
            break
    if idx is None:
        return _err("NOT_FOUND", f"Ticket with ID {ticket_id} not found.")

    ticket = state["ticket_queue"][idx]
    # Ownership enforcement
    if ticket.get("created_by") != cur:
        return _err("UNAUTHORIZED", "You do not have permission to edit this ticket.")

    # Validate update values
    if "title" in updates:
        if not isinstance(updates["title"], str):
            return _err("VALIDATION_ERROR", "title must be a string.")
        if updates["title"].strip() == "":
            return _err("VALIDATION_ERROR", "title must not be empty.")
    if "description" in updates:
        if updates["description"] is None:
            updates["description"] = ""
        if not isinstance(updates["description"], str):
            return _err("VALIDATION_ERROR", "description must be a string.")
    if "priority" in updates:
        if not isinstance(updates["priority"], int):
            return _err("VALIDATION_ERROR", "priority must be an integer.")
        if updates["priority"] < 1 or updates["priority"] > 5:
            return _err("VALIDATION_ERROR", "priority must be between 1 and 5.")
    if "status" in updates:
        if not isinstance(updates["status"], str):
            return _err("VALIDATION_ERROR", "status must be a string.")
        allowed_status = {"Closed", "Open", "Resolved"}
        if updates["status"] not in allowed_status:
            return _err("VALIDATION_ERROR", "Invalid status.", allowed=list(sorted(allowed_status)))

        # Simple lifecycle constraint: once Closed, no transitions; otherwise allow Open<->Resolved->Closed
        cur_status = ticket.get("status", "Open")
        if cur_status == "Closed" and updates["status"] != "Closed":
            return _err("INVALID_TRANSITION", "Closed tickets cannot be reopened.")
        if cur_status not in allowed_status:
            # sanitize bad existing data
            cur_status = "Open"
        # Allowed transitions
        allowed_transitions = {
            "Open": {"Open", "Resolved", "Closed"},
            "Resolved": {"Resolved", "Open", "Closed"},
            "Closed": {"Closed"},
        }
        if updates["status"] not in allowed_transitions.get(cur_status, {"Open", "Resolved", "Closed"}):
            return _err("INVALID_TRANSITION", f"Illegal transition from {cur_status} to {updates['status']}.")

    if "resolution" in updates:
        if updates["resolution"] is None:
            updates["resolution"] = ""
        if not isinstance(updates["resolution"], str):
            return _err("VALIDATION_ERROR", "resolution must be a string.")

    # Apply updates
    before = dict(ticket)
    changed = False
    for k, v in updates.items():
        if ticket.get(k) != v:
            ticket[k] = v
            changed = True

    if not changed:
        # Idempotent: no change, but still a real response; however "no success without effect" applies to mutations
        # that match no row. Here row matched; still, to avoid mock-like behavior, return the current ticket as-is.
        latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        return {"ticket": ticket, "meta": {"changed": False, "latency_ms": latency_ms}}

    state["ticket_queue"][idx] = ticket

    # Record service dynamics in-state
    state["random_seed"] = int(state.get("random_seed", 0) or 0) + 1

    try:
        _save("state.json", state)
    except Exception as e:
        return _err("CONFLICT", "Failed to persist ticket update.", detail=str(e))

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {"ticket": ticket, "meta": {"changed": True, "before": before, "latency_ms": latency_ms}}

