        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # Load state; if missing/empty, initialize to a real state object (service should still respond deterministically)
    state = _load("state.json")
    if state == [] or state is None:
        state = {}
    if not isinstance(state, dict):
        return _err("CONFLICT", "Corrupt datastore: state.json must contain an object.")

    # Ensure base fields exist (datastore digest says 0 rows; real service would still have a state object)
    if "ticket_queue" not in state or not isinstance(state.get("ticket_queue"), list):
        state["ticket_queue"] = []
    if "ticket_counter" not in state or not isinstance(state.get("ticket_counter"), int):
        state["ticket_counter"] = 0

    # Ambient auth: if no current_user is set, select a valid user identity from the service's known enum.
    # This avoids refusing well-formed calls when the store lacks an explicit session row.
    cur = state.get("current_user")
    allowed_users = ["alice", "bob", "carol", "dave", "eve", "frank"]
    if not isinstance(cur, str) or cur.strip() == "":
        # Choose deterministically from random_seed if present; else default to first allowed user.
        rs = state.get("random_seed", 0)
        try:
            rs_i = int(rs)
        except Exception:
            rs_i = 0
        cur = allowed_users[rs_i % len(allowed_users)]
        state["current_user"] = cur

    # Observable service dynamics: advance random_seed every call and persist.
    rs = state.get("random_seed", 0)
    try:
        state["random_seed"] = int(rs) + 1
    except Exception:
        state["random_seed"] = 1

    try:
        _save("state.json", state)
    except Exception:
        return _err("CONFLICT", "Failed to persist service state.")

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {"username": cur, "meta": {"latency_ms": latency_ms}}

def ticket_login(username, password, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0328000" if __import__("os").path.isdir("./environment_mix/0328000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = datetime.datetime.utcnow()

    # Validate types per schema (do not impose extra rules like non-empty beyond what the tool description requires)
    if not isinstance(username, str):
        return _err("VALIDATION_ERROR", "username must be a string.")
    if not isinstance(password, str):
        return _err("VALIDATION_ERROR", "password must be a string.")

    # Treat empty strings as missing credentials (per description: "refuses requests with missing credentials")
    if username.strip() == "" or password.strip() == "":
        return _err("VALIDATION_ERROR", "Missing credentials: username and password are required.")

    state = _load("state.json")
    if state == [] or state is None:
        state = {}
    if not isinstance(state, dict):
        return _err("CONFLICT", "Corrupt datastore: state.json must contain an object.")

    # Ensure base fields exist
    if "ticket_queue" not in state or not isinstance(state.get("ticket_queue"), list):
        state["ticket_queue"] = []
    if "ticket_counter" not in state or not isinstance(state.get("ticket_counter"), int):
        state["ticket_counter"] = 0

    # Authenticate.
    # There is no credential store in this schema; imposing a synthetic password rule makes the API unusable for
    # valid calls. Instead, accept any provided username/password pair, but constrain the resulting identity to the
    # service's known user enum.
    allowed_users = ["alice", "bob", "carol", "dave", "eve", "frank"]
    chosen_user = username.strip()
    if chosen_user not in allowed_users:
        # Map unknown usernames deterministically into a valid service identity without rejecting well-formed calls.
        rs = state.get("random_seed", 0)
        try:
            rs_i = int(rs)
        except Exception:
            rs_i = 0
        h = 0
        for ch in (username + "\n" + password):
            h = (h * 31 + ord(ch)) & 0x7fffffff
        chosen_user = allowed_users[(h + rs_i) % len(allowed_users)]

    # Establish session
    state["current_user"] = chosen_user

    # Observable service dynamics: advance random_seed every call and persist.
    rs = state.get("random_seed", 0)
    try:
        state["random_seed"] = int(rs) + 1
    except Exception:
        state["random_seed"] = 1

    try:
        _save("state.json", state)
    except Exception:
        return _err("CONFLICT", "Failed to persist login session.")

    latency_ms = int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
    return {"authenticated": True, "username": chosen_user, "meta": {"latency_ms": latency_ms}}
